/**
 * Central analytics event catalogue (TECHNICAL_DESIGN 24.1, AUT-063). Ids and parameter names are snake_case and unique; every event declares its
 * parameter schema here, so the DEBUG validator, the mapper and the providers share ONE definition. Pure, engine-free.
 *
 * Privacy rules enforced by the schema: no free text, no price / currency strings, no device or user identifiers. The only ids allowed are content
 * ids (producer / upgrade / breakthrough / era) and OPAQUE request ids generated by the flows. AUT-064 extends the catalogue by adding entries to
 * `ANALYTICS_EVENT_SCHEMAS` (and to the id table below).
 */
export const ANALYTICS_EVENTS = {
    producerUnlock: 'producer_unlock',
    breakthroughPurchase: 'breakthrough_purchase',
    eraReached: 'era_reached',
    firstRobot: 'first_robot',
    civilizationReached: 'civilization_reached',
    rebootPreview: 'reboot_preview',
    rebootCompleted: 'reboot_completed',
    permanentUpgradePurchase: 'permanent_upgrade_purchase',
    offlineReportShown: 'offline_report_shown',
    offlineCollected: 'offline_collected',
    offlineAutoCollected: 'offline_auto_collected',
    rewardedOpportunity: 'rewarded_opportunity',
    rewardedStart: 'rewarded_start',
    rewardedComplete: 'rewarded_complete',
    rewardedFailure: 'rewarded_failure',
    rewardedUnavailable: 'rewarded_unavailable',
    purchaseOfferShown: 'purchase_offer_shown',
    purchaseStart: 'purchase_start',
    purchaseComplete: 'purchase_complete',
    purchasePending: 'purchase_pending',
    purchaseCancel: 'purchase_cancel',
    purchaseFailure: 'purchase_failure',
    purchaseRestore: 'purchase_restore',
} as const;

export type AnalyticsEventId = (typeof ANALYTICS_EVENTS)[keyof typeof ANALYTICS_EVENTS];

export type AnalyticsParamKind = 'identifier' | 'opaque_id' | 'enum' | 'integer' | 'boolean';

export interface AnalyticsParamSpec {
    readonly kind: AnalyticsParamKind;
    readonly required: boolean;
    /** enum: the closed list of allowed string values. */
    readonly values?: readonly string[];
    /** integer: inclusive range. */
    readonly min?: number;
    readonly max?: number;
}

export interface AnalyticsEventSchema {
    readonly params: Readonly<Record<string, AnalyticsParamSpec>>;
}

/** Hard cap for every string parameter (identifier / opaque id / enum value). */
export const ANALYTICS_MAX_STRING_LENGTH = 64;
/** Identifier charset: content ids and opaque request ids (letters, digits, `_ . : -`). No spaces, no currency symbols. */
export const ANALYTICS_IDENTIFIER_PATTERN = /^[A-Za-z0-9_.:-]+$/;

export const ANALYTICS_REWARDED_PLACEMENTS = ['offline_double', 'extended_overclock'] as const;
export const ANALYTICS_PRODUCTS = ['founder_pack'] as const;
export const ANALYTICS_OFFLINE_BUCKETS = ['lt_1m', '1_5m', '5_30m', '30m_2h', '2_8h', 'gt_8h'] as const;
export type AnalyticsOfflineBucket = (typeof ANALYTICS_OFFLINE_BUCKETS)[number];

const id = (required = true): AnalyticsParamSpec => ({ kind: 'identifier', required });
const opaque = (required = true): AnalyticsParamSpec => ({ kind: 'opaque_id', required });
const oneOf = (values: readonly string[], required = true): AnalyticsParamSpec => ({ kind: 'enum', required, values });
const int = (min: number, max: number, required = true): AnalyticsParamSpec => ({ kind: 'integer', required, min, max });
const flag = (required = true): AnalyticsParamSpec => ({ kind: 'boolean', required });

const placement = oneOf(ANALYTICS_REWARDED_PLACEMENTS);
const product = oneOf(ANALYTICS_PRODUCTS);
const offlineBucket = oneOf(ANALYTICS_OFFLINE_BUCKETS);

export const ANALYTICS_EVENT_SCHEMAS: Readonly<Record<AnalyticsEventId, AnalyticsEventSchema>> = Object.freeze({
    producer_unlock: { params: { producer_id: id(), source: oneOf(['producer_purchase', 'breakthrough']) } },
    breakthrough_purchase: { params: { breakthrough_id: id() } },
    era_reached: { params: { era_id: id() } },
    first_robot: { params: {} },
    civilization_reached: { params: { civilization: int(1, 10_000) } },
    reboot_preview: { params: {} },
    reboot_completed: { params: { civilization: int(1, 10_000), ai_cores_granted: int(0, 1_000_000_000) } },
    permanent_upgrade_purchase: { params: { upgrade_id: id(), rank: int(1, 10_000) } },
    offline_report_shown: { params: { reason: oneOf(['startup', 'resumed', 'reboot_blocked']), absence_bucket: offlineBucket, cap_applied: flag() } },
    offline_collected: { params: { absence_bucket: offlineBucket, cap_applied: flag(), doubled: flag(), saved: flag(false) } },
    offline_auto_collected: { params: { absence_bucket: offlineBucket, saved: flag(false) } },
    rewarded_opportunity: { params: { placement } },
    rewarded_start: { params: { placement, request_id: opaque() } },
    rewarded_complete: { params: { placement, request_id: opaque(false) } },
    rewarded_failure: { params: { placement, reason: oneOf(['closed', 'failed', 'timeout', 'unverified']), request_id: opaque(false) } },
    rewarded_unavailable: { params: { placement, stage: oneOf(['offer', 'show']) } },
    purchase_offer_shown: { params: { product } },
    purchase_start: { params: { product, request_id: opaque() } },
    purchase_complete: { params: { product, request_id: opaque(false) } },
    purchase_pending: { params: { product, request_id: opaque(false) } },
    purchase_cancel: { params: { product, request_id: opaque(false) } },
    purchase_failure: { params: { product, reason: oneOf(['failed', 'timeout', 'unavailable', 'apply_rejected']), request_id: opaque(false) } },
    purchase_restore: { params: { product } },
});

export function isAnalyticsEventId(value: string): value is AnalyticsEventId {
    return Object.prototype.hasOwnProperty.call(ANALYTICS_EVENT_SCHEMAS, value);
}

/** Buckets an absence duration (seconds) so no exact duration is ever sent. */
export function bucketOfflineSeconds(seconds: number): AnalyticsOfflineBucket {
    const s = Number.isFinite(seconds) && seconds > 0 ? seconds : 0;
    if (s < 60) return 'lt_1m';
    if (s < 300) return '1_5m';
    if (s < 1800) return '5_30m';
    if (s < 7200) return '30m_2h';
    if (s < 28800) return '2_8h';
    return 'gt_8h';
}
